function codePointCompare(a:string,b:string):number{const aa=Array.from(a,c=>c.codePointAt(0)!),bb=Array.from(b,c=>c.codePointAt(0)!);for(let i=0;i<Math.min(aa.length,bb.length);i++)if(aa[i]!==bb[i])return aa[i]-bb[i];return aa.length-bb.length;}
function excluded(file:string):boolean{return file.startsWith('dist/tests/')||/^dist\/native-.*\.cjs$/.test(file);}
function walkScope(scope:string,out:Set<string>):void{
  const absolute=path.join(root,scope);assert.ok(fs.existsSync(absolute),'manifest scope is missing: '+scope);
  const stat=fs.lstatSync(absolute);assert.ok(!stat.isSymbolicLink(),'symlink in product scope: '+scope);
  if(stat.isFile()){if(!excluded(scope))out.add(scope);return;}
  assert.ok(stat.isDirectory(),'unsupported product scope object: '+scope);
  const visit=(dir:string,relative:string)=>{for(const entry of fs.readdirSync(dir,{withFileTypes:true}).sort((a,b)=>codePointCompare(a.name,b.name))){const abs=path.join(dir,entry.name),rel=path.posix.join(relative,entry.name);assert.ok(!entry.isSymbolicLink(),'symlink in product inventory: '+rel);if(entry.isDirectory())visit(abs,rel);else if(entry.isFile()){if(!excluded(rel))out.add(rel);}else throw Error('unsupported product inventory entry: '+rel);}};
  visit(absolute,scope);
}
function productHashes():Record<string,string>{
  const files=new Set<string>();for(const scope of productScopes)walkScope(scope,files);
  return Object.fromEntries([...files].sort(codePointCompare).map(file=>[file,createHash('sha256').update(fs.readFileSync(path.join(root,file))).digest('hex')]));
}
function canonicalInventory(hashes:Record<string,string>):string{return createHash('sha256').update(Object.entries(hashes).sort(([a],[b])=>codePointCompare(a,b)).map(([file,hash])=>`${hash}  ${file}\n`).join(''),'utf8').digest('hex');}
function record(name:string,detail?:unknown,statusValue:Status='PASS'):void{const item={name,status:statusValue,detail};checks.push(item);try{fs.mkdirSync(evidenceDir,{recursive:true,mode:0o700});fs.appendFileSync(progressPath,JSON.stringify({at:new Date().toISOString(),...item})+'\n',{mode:0o600});}catch(error){harnessIssues.push('progress log: '+String(error));}}
function page(win:BrowserWindowType):string|null{try{return new URL(win.webContents.getURL()).searchParams.get('page');}catch{return null;}}
function snapshots():Array<Record<string,unknown>>{return [...traces.values()].map(t=>{try{t.last={visible:t.visible(),focused:t.focused()};const win=BrowserWindow.fromId(t.id);return{id:t.id,page:t.page,...t.last,destroyed:!win||win.isDestroyed(),url:win&&!win.isDestroyed()?win.webContents.getURL()||null:null};}catch(error){return{id:t.id,page:t.page,...t.last,destroyed:true,error:String(error)};}});}
const boundaryInstrumentation='(()=>{if(window.__compact0122Boundary)return true;window.__compact0122Boundary=true;window.__compact0122Keys=0;window.__compact0122Csp=[];for(const t of ["keydown","keyup","keypress"])document.addEventListener(t,()=>window.__compact0122Keys++,true);document.addEventListener("securitypolicyviolation",e=>window.__compact0122Csp.push({directive:e.violatedDirective,blocked:e.blockedURI,sample:e.sample||""}),true);return true})()';
new vm.Script(boundaryInstrumentation,{filename:'compact-0122-renderer-boundary.js'});
function staticParseCanary():void{const refs=[villageSelector('gift-0'),villageSelector('build')],sources=[`(()=>{const e=document.querySelector(${JSON.stringify(refs[0])});return!!e?.closest("button")})()`,`(()=>[...document.querySelectorAll(".v-material-tray > .v-material:not([hidden])")].map(e=>e.dataset.vRef))()`,`(()=>{for(const e of document.querySelectorAll(".popover-content,#cContent"))e.scrollTop=0;return document.scrollingElement?.scrollTop||0})()`,`(()=>{const b=document.querySelector(${JSON.stringify(refs[1])}),r=b?.getBoundingClientRect();return!!r&&document.elementFromPoint(r.left+r.width/2,r.top+r.height/2)?.closest("button")===b})()`];for(const source of sources){new vm.Script(source,{filename:'compact-0122-renderer-prelaunch-canary.js'});inlineSourceDigests.add(createHash('sha256').update(source).digest('hex'));}record('renderer inline JavaScript parse canary passed before app startup',{count:sources.length,policy:'Every executeJavaScript snippet is also compiled with vm.Script before renderer evaluation.'});}
function track(win:BrowserWindowType):void{
  if(traces.has(win.id))return;const visible=win.isVisible.bind(win),focused=win.isFocused.bind(win);traces.set(win.id,{id:win.id,page:page(win),visible,focused,last:{visible:visible(),focused:focused()}});keyEvents[win.id]=null;cspEvents[win.id]=null;
  const instrument=()=>{if(win.isDestroyed())return;void win.webContents.executeJavaScript(boundaryInstrumentation).catch(error=>{if(!win.isDestroyed())harnessIssues.push('renderer boundary '+win.id+': '+String(error));});};
  win.webContents.on('console-message',(event:any)=>{if(event.level==='error')errors.push(JSON.stringify({window:win.id,page:page(win),message:String(event.message).slice(0,900),sourceId:event.sourceId,lineNumber:event.lineNumber}));});
  win.webContents.on('did-finish-load',()=>{const t=traces.get(win.id);if(t)t.page=page(win);instrument();});if(!win.webContents.isLoadingMainFrame())instrument();
}
function profile():Profile{const p=shell?.game.state.profile;assert.ok(p,'isolated GameWorker profile unavailable: '+(shell?.game.state.error||'loading'));return p;}
function overlay():BrowserWindowType{const w=shell?.overlay;assert.ok(w&&!w.isDestroyed(),'hidden street overlay unavailable');return w;}
function popup():BrowserWindowType{const w=shell?.popupWindow;assert.ok(w&&!w.isDestroyed(),'hidden shop/alchemy popup unavailable');return w;}
function arena():BrowserWindowType{const w=shell?.arenaWindow;assert.ok(w&&!w.isDestroyed(),'hidden camp window unavailable');return w;}
async function until(fn:()=>Promise<boolean>|boolean,label:string,timeout=25_000):Promise<void>{const end=Date.now()+timeout;while(Date.now()<end){if(await fn())return;await new Promise(resolve=>setTimeout(resolve,35));}throw Error('timeout: '+label);}
async function js<T=unknown>(win:BrowserWindowType,source:string):Promise<T>{let timer:ReturnType<typeof setTimeout>|undefined;try{new vm.Script(source,{filename:'compact-0122-renderer-inline.js'});inlineSourceDigests.add(createHash('sha256').update(source).digest('hex'));return await Promise.race([win.webContents.executeJavaScript(source) as Promise<T>,new Promise<T>((_,reject)=>{timer=setTimeout(()=>reject(Error('renderer evaluation timeout '+win.id)),15_000);})]);}catch(error){throw Error('renderer evaluation failed in '+win.id+': '+String(error)+'; source='+source.slice(0,450));}finally{if(timer)clearTimeout(timer);}}
async function visible(win:BrowserWindowType,selector:string):Promise<boolean>{return js(win,`(()=>{const e=document.querySelector(${JSON.stringify(selector)}),s=e&&getComputedStyle(e);return!!e&&!e.hidden&&!e.closest('[hidden]')&&!e.closest('details:not([open])')&&s?.display!=='none'&&s?.visibility!=='hidden'})()`);}
function selectorForId(id:string):string{return '#'+id;}
function villageSelector(ref:string):string{return '#villageUi [data-v-ref='+JSON.stringify(ref)+']';}
function imageUrl(raw:string|null):string|null{if(!raw)return null;const start=raw.indexOf('url(');if(start<0)return null;const body=raw.slice(start+4,raw.lastIndexOf(')')).trim();return body.replace(/^['"]|['"]$/g,'')||null;}

async function setViewport(win:BrowserWindowType,width:760|1040,height=650):Promise<void>{
  const d=win.webContents.debugger,wasAttached=d.isAttached();if(!wasAttached){d.attach('1.3');viewportSessions.set(win.id,false);}else if(!viewportSessions.has(win.id))viewportSessions.set(win.id,true);
  await d.sendCommand('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:false});await until(()=>js<boolean>(win,`innerWidth===${width}&&innerHeight===${height}`),'CSS viewport '+width+'x'+height);
  record('hidden Electron CSS viewport '+width+'x'+height,{width,height,outerWindow:win.getSize(),nativeVisible:win.isVisible(),nativeFocused:win.isFocused(),method:'CDP Emulation.setDeviceMetricsOverride; no visible-screen claim'});
}
async function clearViewport(win:BrowserWindowType):Promise<void>{const d=win.webContents.debugger;if(!d.isAttached())return;const session=viewportSessions.get(win.id);try{await d.sendCommand('Emulation.clearDeviceMetricsOverride');}finally{if(session===false&&d.isAttached())d.detach();viewportSessions.delete(win.id);}}
