async function auditArt(win:BrowserWindowType,label:string,selector:string,minimum=1):Promise<void>{
  const art=await js<any>(win,`(()=>{const sel=${JSON.stringify(selector)},els=[...document.querySelectorAll(sel)];return{selector:sel,els:els.map(e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect(),bg=s.backgroundImage||getComputedStyle(e,"::before").backgroundImage||"none",img=e instanceof HTMLImageElement?{src:e.currentSrc||e.src,complete:e.complete,naturalWidth:e.naturalWidth,naturalHeight:e.naturalHeight}:null;return{tag:e.tagName,id:e.id||e.dataset.vRef||null,hidden:!!e.hidden||!!e.closest("[hidden]"),rect:{x:r.x,y:r.y,width:r.width,height:r.height},background:bg,img}})}})()`);
  assert.ok(art.els.length>=minimum,label+' expected art selector '+selector);const rows=[];
  for(const item of art.els){assert.equal(item.hidden,false,label+' artwork hidden: '+JSON.stringify(item));let url=item.img?.src||imageUrl(item.background);assert.ok(url,label+' has no rendered local picture: '+JSON.stringify(item));const parsed=new URL(url);assert.equal(parsed.protocol,'file:',label+' artwork must load from a local asset');const file=fileURLToPath(parsed);assert.ok(fs.statSync(file).size>1000,label+' source art file too small: '+file);if(item.img){assert.equal(item.img.complete,true,label+' image decode incomplete');assert.ok(item.img.naturalWidth>0&&item.img.naturalHeight>0,label+' image natural dimensions empty');}rows.push({id:item.id,asset:path.relative(root,file),bytes:fs.statSync(file).size,rect:item.rect});}
  record('loaded local pixel art · '+label,{selector,art:rows,evidence:'computed renderer image source in the real hidden Electron window'});
}
async function clickAt(win:BrowserWindowType,selector:string,label:string,requirePicture=false):Promise<Record<string,unknown>>{
  const measured=await js<any>(win,`(()=>{const b=document.querySelector(${JSON.stringify(selector)});if(!b)return{ok:false,why:"missing"};const style=getComputedStyle(b),r=b.getBoundingClientRect(),hidden=!!b.hidden||!!b.closest("[hidden]")||!!b.closest("details:not([open])")||style.display==="none"||style.visibility==="hidden";if(hidden||b.disabled)return{ok:false,why:hidden?"hidden":"disabled",disabled:!!b.disabled};const art=b.querySelector(".inner-art,.ls-item-art,.a-good-art,.tw-material-art,.v-sprite,.b-buddy-art,.b-rarity-art,.b-path-emblem,.life-food-art,.cw-food-art,.cw-food-thumb,.life-relic-art,.cs-buddy-art");const ar=art?.getBoundingClientRect();const useArt=!!art&&!!ar&&ar.width>0&&ar.height>0;const x=useArt?ar.left+ar.width/2:r.left+r.width/2,y=useArt?ar.top+ar.height/2:r.top+r.height/2,h=document.elementFromPoint(x,y),button=b.closest("button"),background=art?getComputedStyle(art).backgroundImage:getComputedStyle(b,"::before").backgroundImage;return{ok:!!button&&h?.closest("button")==button&&x>=0&&y>=0&&x<=innerWidth&&y<=innerHeight&&r.left>=-1&&r.top>=-1&&r.right<=innerWidth+1&&r.bottom<=innerHeight+1,why:"center point must stay in the initial viewport and land in the same button",x,y,pointSource:useArt?"rendered child-art center":"visible button center",tag:h?.tagName||null,hitId:h?.id||null,buttonId:button?.id||button?.dataset.vRef||null,disabled:!!button?.disabled,label:button?.getAttribute("aria-label")||button?.dataset.tooltip||button?.textContent?.trim()||"",background,scrollTop:document.scrollingElement?.scrollTop||0}})()`);
  assert.ok(measured.ok,label+' coordinate hit failed without scrolling: '+JSON.stringify(measured));assert.equal(measured.scrollTop,0,label+' click must start at scrollTop 0');if(requirePicture)assert.ok(imageUrl(measured.background),label+' control lacks rendered image at actual pointer coordinate');
  const dispatch=await js<any>(win,`(()=>{const x=${measured.x},y=${measured.y},h=document.elementFromPoint(x,y),b=h?.closest("button"),before={x,y,tag:h?.tagName||null,id:h?.id||null,buttonId:b?.id||b?.dataset.vRef||null};if(!b||b.disabled||b.id!==${JSON.stringify(measured.buttonId)}&&b.dataset.vRef!==${JSON.stringify(measured.buttonId)})return{ok:false,before};for(const type of ["pointerdown","pointerup"])h.dispatchEvent(new PointerEvent(type,{bubbles:true,cancelable:true,view:window,clientX:x,clientY:y,pointerType:"mouse",button:0}));h.dispatchEvent(new MouseEvent("click",{bubbles:true,cancelable:true,view:window,clientX:x,clientY:y,button:0}));return{ok:true,before}})()`);
  assert.ok(dispatch.ok,label+' actual elementFromPoint dispatch missed target: '+JSON.stringify(dispatch));record('software coordinate pointer hit on actual rendered control · '+label,{...measured,dispatched:dispatch.before,evidence:'PointerEvent and MouseEvent on actual elementFromPoint in hidden Electron renderer; software input only'});return measured;
}
async function localClick(win:BrowserWindowType,selector:string,label:string,ready:()=>Promise<boolean>):Promise<Record<string,unknown>>{const seq=profile().sequence,hit=await clickAt(win,selector,label);await until(ready,label+' settles visually');assert.equal(profile().sequence,seq,label+' local view selection must not mutate the profile');return hit;}
async function actionClick(win:BrowserWindowType,selector:string,label:string,verify:(before:Profile,after:Profile)=>void):Promise<Profile>{const before=structuredClone(profile()),hit=await clickAt(win,selector,label);await until(()=>profile().sequence===before.sequence+1,'actual GameWorker receipt for '+label);const after=profile();verify(before,after);record('actual UI action reached GameWorker · '+label,{sequenceBefore:before.sequence,sequenceAfter:after.sequence,coinsBefore:before.coins,coinsAfter:after.coins,notice:after.notice,hit,runtime:'actual Electron Shell IPC and GameWorker; isolated profile'});return after;}
async function openTab(win:BrowserWindowType,id:string,panel:string):Promise<void>{const seq=profile().sequence;await clickAt(win,'#'+id,'open '+id);await until(async()=>await visible(win,'#'+panel)&&await js<boolean>(win,`document.getElementById(${JSON.stringify(id)})?.getAttribute('aria-selected')==="true"`),id+' panel');assert.equal(profile().sequence,seq,'navigation changed profile');}
async function capture(win:BrowserWindowType,label:string):Promise<void>{await new Promise(resolve=>setTimeout(resolve,80));assert.equal(win.isVisible(),false,'capture target became visible');assert.equal(win.isFocused(),false,'capture target became focused');const image=await win.webContents.capturePage(),size=image.getSize(),bytes=image.toPNG(),file=path.join(evidenceDir,`screen-${fixtureMode}-${runId}-${label}.png`);assert.ok(size.width>0&&size.height>0&&bytes.length>2500,label+' screenshot is empty');fs.writeFileSync(file,bytes,{flag:'wx',mode:0o600});screenshots.push(file);record('hidden native renderer capture · '+label,{file,size,bytes:bytes.length,native:{visible:false,focused:false},method:'Electron webContents.capturePage; not browser preview, not physical display evidence'});}
async function atBothWidths<T>(win:BrowserWindowType,label:string,fn:(width:760|1040)=>Promise<T>):Promise<void>{for(const width of [760,1040] as const){await setViewport(win,width);await resetInitialScroll(win);await fn(width);await capture(win,label+'-'+width+'x650');}}
async function auditFitAtBothWidthsCollecting(win:BrowserWindowType,label:string,selectors:string[],criticalButtons:string[],minimumMatches:Record<string,number>={}):Promise<void>{
  const redWidths:Array<{width:number;error:string}>=[];
  for(const width of [760,1040] as const){await setViewport(win,width);const scroll=await resetInitialScroll(win);assert.equal(scroll.documentTop,0,label+' must start at the top for '+width+'px');const priorScreenshots=screenshots.length;try{await auditFit(win,label,selectors,criticalButtons,minimumMatches);await capture(win,label.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-'+width+'x650');}catch(error){redWidths.push({width,error:String(error)});record('legacy compact field fit RED preserved · '+label+' · '+width+'px',{width,error:String(error),scrollTop:0,source:'actual hidden Electron renderer'},'FAIL');if(screenshots.length===priorScreenshots){try{await capture(win,'red-'+label.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-'+width+'x650');}catch(captureError){harnessIssues.push('legacy field fallback screenshot '+label+' '+width+': '+String(captureError));}}}}
  if(redWidths.length)legacyFitFailures.push({label,redWidths});
}

async function scenePoint(win:BrowserWindowType,x:number,y:number,label:string):Promise<Record<string,unknown>>{const result=await js<any>(win,`(()=>{const x=${x},y=${y},e=document.elementFromPoint(x,y),b=e?.closest("button");return{ok:!!e&&x>=0&&y>=0&&x<=innerWidth&&y<=innerHeight,x,y,tag:e?.tagName||null,id:e?.id||null,buttonId:b?.id||null}})()`);assert.ok(result.ok,label+' scene coordinate unavailable: '+JSON.stringify(result));await js(win,`(()=>{const e=document.elementFromPoint(${x},${y});for(const type of ["pointerdown","pointerup"])e.dispatchEvent(new PointerEvent(type,{bubbles:true,cancelable:true,view:window,clientX:${x},clientY:${y},pointerType:"mouse",button:0}));e.dispatchEvent(new MouseEvent("click",{bubbles:true,cancelable:true,view:window,clientX:${x},clientY:${y},button:0}));return true})()`);record('software point hit in actual street scene · '+label,{...result,evidence:'software PointerEvent and MouseEvent; native app hidden'});return result;}
