  if(Reflect.get(shell!,'view')!=='interior'||Reflect.get(shell!,'activeShop')!==shop){await clickAt(street,'[data-shop="'+shop+'"]','street shop sign '+shop);await until(()=>Reflect.get(shell!,'view')==='interior'&&Reflect.get(shell!,'activeShop')===shop,'street entered '+shop);}
