function makeFixture(now:number,mode:'fresh'|'rich'):Profile{
  const p=initialProfile(now);p.tick=1000;p.wallAt=now;
  if(mode==='fresh'){p.job='apprentice';p.coins=50;p.totals.earned=50;p.bag.flour=4;return parseProfile(p);}
  p.job='keeper';p.coins=500_000;p.xp=20_000;p.totals.earned=p.coins;p.totals.crafted=200;p.business.managed=true;p.leisure.rooms=40;p.leisure.harvests=40;p.leisure.cooked=100;p.leisure.clears=[5,5,5,5,5];
  p.leisure.materials={...p.leisure.materials,ore:500,herb:500,berry:500,mushroom:500,tea:500,biscuit:500,soup:500,pumpkin:500,snowflower:500,pie:500,snowtea:500};p.bag.flour=500;p.bag.gel=500;p.bag.ration=20;p.bag.crystal=20;
  p.atelier=initialAtelier();p.atelier.facilities={kitchen:3,still:3,counter:3};p.bag.gel=20;p.camp=initialCamp();for(const id of BUDDY_ORDER)p.leisure.companions[id]=10;p.leisure.active='slime';p.leisure.journal.dust=100;p.leisure.journal.buildings.archive=1;p.leisure.journal.relics[0]=1;p.leisure.bonds=initialBonds();p.leisure.bonds.tokens=120;p.leisure.bonds.relics[0]=1;p.leisure.bonds.progress.deer.path=null;p.village=initialVillage();p.village.regulars.miner.served=2;
  return parseProfile(p);
}
